var docs = UnityEngine.Object.FindObjectsByType<UnityEngine.UIElements.UIDocument>(UnityEngine.FindObjectsSortMode.None);
return docs.Select(d => new { name = d.name, asset = d.visualTreeAsset == null ? null : UnityEditor.AssetDatabase.GetAssetPath(d.visualTreeAsset), labels = UnityEngine.UIElements.UQueryExtensions.Query<UnityEngine.UIElements.Label>(d.rootVisualElement).ToList().Select(l => new { name=l.name, text=l.text }).ToArray(), buttons = UnityEngine.UIElements.UQueryExtensions.Query<UnityEngine.UIElements.Button>(d.rootVisualElement).ToList().Select(b => new {name=b.name, text=b.text, enabled=b.enabledInHierarchy}).ToArray() }).ToArray();
